 126: function runRelease(projectRoot = process.cwd(), overrides = {}) {
 127:   const resolvedRoot = path.resolve(projectRoot);
 128:   const operations = {
 129:     copyProjectInputs,
 130:     createStageRoot,
 131:     runNativeRelease,
 132:     ...overrides,
 133:   };
 134:   const destination = prepareReleaseArtifact(resolvedRoot);
 135:   if (!needsAsciiStaging(resolvedRoot)) {
 136:     operations.runNativeRelease(resolvedRoot);
 137:     return findExpectedReleaseArtifact(resolvedRoot);
 138:   }
 139: 
 140:   const stageRoot = operations.createStageRoot();
 141:   const stageProject = path.join(stageRoot, 'project');
 142:   try {
 143:     operations.copyProjectInputs(resolvedRoot, stageProject);
 144:     prepareReleaseArtifact(stageProject);
 145:     operations.runNativeRelease(stageProject);
 146:     const artifact = findExpectedReleaseArtifact(stageProject);
 147:     return publishReleaseArtifact(artifact, destination);
 148:   } finally {
 149:     fs.rmSync(stageRoot, { recursive: true, force: true });
 150:   }
 151: }
 152: 
 153: if (require.main === module) {
 154:   try {
 155:     const artifact = runRelease();
 156:     console.log(`Release RPK: ${artifact}`);
 157:   } catch (error) {
 158:     console.error(error.message);
 159:     process.exitCode = 1;
 160:   }
 161: }
