   4: function createResourceController(options) {
   5:   const config = options || {};
   6:   const healthTypes = Array.isArray(config.healthTypes) ? config.healthTypes.slice() : [];
   7:   let visible = false;
   8:   let healthState = subscriptions.createSubscriptionState(healthTypes);
   9:   let healthEpochs = {};
  10:   let recentEpoch = 0;
  11:   let recentPending = false;
  12:   let motionEpoch = 0;
  13:   let motionActive = false;
  14: 
  15:   function nextHealthEpoch(type) {
  16:     const key = String(type);
  17:     const next = (healthEpochs[key] || 0) + 1;
  18:     healthEpochs = { ...healthEpochs, [key]: next };
  19:     return next;
  20:   }
  21: 
  22:   function isCurrentHealth(type, epoch) {
  23:     return visible
  24:       && healthEpochs[String(type)] === epoch
  25:       && healthState.activeTypes.includes(type);
  26:   }
  27: 
  28:   function startRecentHealth() {
  29:     if (!visible || recentPending || typeof config.getRecentHealth !== 'function') return;
  30:     const epoch = recentEpoch + 1;
  31:     recentEpoch = epoch;
  32:     recentPending = true;
  33:     let request;
  34:     try {
  35:       request = config.getRecentHealth(healthTypes);
  36:     } catch (error) {
  37:       if (recentEpoch === epoch) recentPending = false;
  38:       if (visible && recentEpoch === epoch && config.onHealthError) config.onHealthError(error);
  39:       return;
  40:     }
  41:     Promise.resolve(request).then(
  42:       (samples) => {
  43:         if (recentEpoch !== epoch) return;
  44:         recentPending = false;
  45:         if (!visible || !Array.isArray(samples) || !config.onHealthSample) return;
  46:         samples.forEach((sample) => config.onHealthSample(sample));
  47:       },
  48:       (error) => {
  49:         if (recentEpoch !== epoch) return;
  50:         recentPending = false;
  51:         if (visible && config.onHealthError) config.onHealthError(error);
  52:       },
  53:     );
  54:   }
  55: 
  56:   function startHealth(loadRecent) {
  57:     if (!visible) return;
  58:     if (loadRecent) startRecentHealth();
  59:     subscriptions.typesToSubscribe(healthState).forEach((type) => {
  60:       const epoch = nextHealthEpoch(type);
  61:       healthState = subscriptions.markSubscribed(healthState, type);
  62:       const onSample = (sample) => {
  63:         if (isCurrentHealth(type, epoch) && config.onHealthSample) config.onHealthSample(sample);
  64:       };
  65:       const onError = (error) => {
  66:         if (healthEpochs[String(type)] !== epoch) return;
  67:         healthState = subscriptions.markUnsubscribed(healthState, type);
  68:         if (visible && config.onHealthError) config.onHealthError(error);
  69:       };
  70:       try {
  71:         config.subscribeHealth(type, onSample, onError);
  72:       } catch (error) {
  73:         onError(error);
  74:       }
  75:     });
  76:   }
  77: 
  78:   function stopHealth() {
  79:     const failures = [];
  80:     subscriptions.typesToUnsubscribe(healthState).forEach((type) => {
  81:       nextHealthEpoch(type);
  82:       healthState = subscriptions.markUnsubscribed(healthState, type);
  83:       try {
  84:         const result = config.unsubscribeHealth(type);
  85:         if (result && result.ok === false) failures.push({ type, error: result.error });
  86:       } catch (error) {
  87:         failures.push({ type, error });
  88:       }
  89:     });
  90:     return failures;
  91:   }
  92: 
  93:   function stopMotion() {
  94:     const wasActive = motionActive;
  95:     motionEpoch += 1;
  96:     motionActive = false;
  97:     if (!wasActive) return [];
  98:     try {
  99:       const result = config.unsubscribeMotion();
 100:       return result && result.ok === false ? [result.error] : [];
 101:     } catch (error) {
 102:       return [error];
 103:     }
 104:   }
 105: 
 106:   function startMotion() {
 107:     if (!visible || motionActive) return false;
 108:     motionActive = true;
 109:     const epoch = motionEpoch + 1;
 110:     motionEpoch = epoch;
 111:     const onSample = (sample) => {
 112:       if (visible && motionActive && motionEpoch === epoch && config.onMotionSample) {
 113:         config.onMotionSample(sample);
 114:       }
 115:     };
 116:     const onError = (error) => {
 117:       if (!visible || !motionActive || motionEpoch !== epoch) return;
 118:       stopMotion();
 119:       if (visible && config.onMotionError) config.onMotionError(error);
 120:     };
 121:     try {
 122:       config.subscribeMotion(onSample, onError);
 123:     } catch (error) {
 124:       onError(error);
 125:     }
 126:     return motionActive;
 127:   }
 128: 
 129:   function enterForeground() {
 130:     visible = true;
 131:   }
 132: 
 133:   function leaveForeground() {
 134:     visible = false;
 135:     recentEpoch += 1;
 136:     recentPending = false;
 137:     healthTypes.forEach((type) => nextHealthEpoch(type));
 138:     motionEpoch += 1;
 139:   }
 140: 
 141:   return {
 142:     enterForeground,
 143:     leaveForeground,
 144:     startHealth,
 145:     stopHealth,
 146:     startMotion,
 147:     stopMotion,
 148:   };
 149: }
 150: 
 151: function resumeSession(sessionClock, now, handlers) {
 152:   const actions = handlers || {};
 153:   const resumedClock = clock.resumeClock(sessionClock, now);
 154:   if (actions.updateClock) actions.updateClock(resumedClock);
 155:   if (clock.isComplete(resumedClock, now)) {
 156:     if (actions.complete) actions.complete();
 157:     return { clock: resumedClock, completed: true };
 158:   }
 159:   if (actions.rearm) actions.rearm(resumedClock);
 160:   return { clock: resumedClock, completed: false };
 161: }
 162: 
 163: module.exports = { createResourceController, resumeSession };

